for t in ('∃ w : Fin 16 → V, InternalZero Sign16CurrentExpression.expression w','∃ w : Fin 17 → V, InternalZero Sign17CurrentExpression.expression w','Sign16CurrentSeedIff.exists_same_input (1 : V)','Sign16CurrentExpression.eval_expression','Sign17CurrentExpression.eval_expression','Fin.cons_self_tail v','Fin.tail v'):assert t in s
