checks=[('reviews/nine-sharing-sign16-current-iff-terminal-independent/check.py','e966b4098009462caaf806552bba21353237f1aa76188f2e9e687f74e8b7fa75'),('reviews/nine-sharing-sign16-expression-eval-terminal-independent/check.py','cdea86d3f76d5a9c1b05b25591bad5e7b5a1701ae6ebb0e156a49af07e40cd17'),('reviews/nine-sharing-sign17-expression-eval-terminal-independent/check.py','9ccc0e4d545a62edf5338d8220c843e619bc65a87ad302569aa8f02dba2eec49')]
